// Keep the tables that should be scanned: drop this template's own tables and any name the policy excludes.
const policy = $('Set Scan Policy').first().json;
const excl = String(policy.exclude_name_patterns || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
const tables = $input.all().map(i => i.json).filter(t => t && t.name);
const keep = tables.filter(t => { const n = String(t.name).toLowerCase(); return !excl.some(p => n.startsWith(p) || n === p); });
return keep.map(t => ({ json: { table_id: t.id, table_name: t.name, columns: (t.columns || []).map(c => ({ name: c.name, type: c.type })) } }));

// Runs once per table inside the loop. Sees the table's columns and a few sampled rows; writes one item per column.
// Values never leave this node unmasked: only a shape such as j***@***.com or ##### is kept.
const table = $('Loop Over Tables').first().json;
const policy = $('Set Scan Policy').first().json;
const patterns = $('Load Detection Patterns').all().map(i => i.json).filter(p => p && p.pattern_key);
const rows = $input.all().map(i => i.json).filter(r => r && typeof r === 'object' && Object.keys(r).length);
const minConf = Number(policy.min_confidence) || 60;
const re = (s) => { try { return s ? new RegExp(s, 'i') : null; } catch (e) { return null; } };
const mask = (v) => {
  if (v === null || v === undefined || v === '') return '';
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return 'YYYY-MM-DD' + (s.length > 10 ? 'T..' : '');
  if (/^[-+]?\d+([.,]\d+)?$/.test(s)) return '#'.repeat(Math.min(s.length, 12));
  if (/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(s)) { const [u, d] = s.split('@'); const tld = d.slice(d.lastIndexOf('.')); return u[0] + '***@***' + tld; }
  if (s.length <= 3) return '*'.repeat(s.length);
  return s[0] + '*'.repeat(Math.min(s.length - 1, 15)) + (s.length > 16 ? '..' : '');
};
const out = [];
const cols = Array.isArray(table.columns) ? table.columns : [];
const isDate = v => /^\d{4}-\d{2}-\d{2}/.test(String(v));           // dates are never phones, IBANs or IPs
// A long unbroken alphanumeric run is an id, a hash or a token, never a phone number in free text.
// Without this every session_id, run_id and *_hash column scores as contact data, because such a
// value contains a long run of digits and the free-text phone scan only asks for digits.
// Only the free-text scan uses this: the pattern regexes are anchored, and an IBAN is a real token.
const looksLikeToken = v => /^[A-Za-z0-9_-]{16,}$/.test(String(v).trim());
const stripDates = s => String(s).replace(/\d{4}-\d{2}-\d{2}(T[0-9:.Z+\-]+)?/g, ' ');
for (const col of cols) {
  const name = String(col.name || '');
  const samples = rows.map(r => r[name]).filter(v => v !== null && v !== undefined && v !== '').slice(0, 10);
  let best = null;
  for (const p of patterns) {
    const nameHit = re(p.name_regex) && re(p.name_regex).test(name);
    const vre = re(p.value_regex);
    const valueHits = vre ? samples.filter(v => !isDate(v) && vre.test(String(v))).length : 0;
    const valueHit = valueHits > 0 && valueHits >= Math.ceil(samples.length / 2);
    if (!nameHit && !valueHit) continue;
    const conf = nameHit && valueHit ? 95 : valueHit ? 85 : (p.sensitivity === 'possible' ? 50 : 70);
    const source = nameHit && valueHit ? 'name+value' : valueHit ? 'value' : 'name';
    const evidence = (nameHit ? 'column name matches ' + p.pattern_key : '') + (nameHit && valueHit ? '; ' : '') + (valueHit ? valueHits + ' of ' + samples.length + ' sampled values look like ' + p.note : '');
    if (!best || conf > best.confidence || (conf === best.confidence && p.sensitivity === 'special')) best = { category: p.category, sensitivity: p.sensitivity, confidence: conf, source, evidence, pattern_key: p.pattern_key };
  }
  // free-text columns: check the sampled values themselves for emails or phones, whatever the column is called
  if (!best || best.sensitivity === 'possible') {
    const emailRe = /[^@\s]+@[^@\s]+\.[a-z]{2,}/i, phoneRe = /\+?[0-9][0-9 ()\-]{7,}[0-9]/;
    const hits = samples.filter(v => !looksLikeToken(v) && (emailRe.test(String(v)) || phoneRe.test(stripDates(v)))).length;
    if (hits) best = { category: 'contact', sensitivity: 'personal', confidence: 80, source: 'value', evidence: hits + ' of ' + samples.length + ' sampled values contain an email address or phone number inside free text', pattern_key: 'free_text_contact' };
  }
  const personal = !!best && best.confidence >= minConf && best.sensitivity !== 'possible';
  out.push({ json: {
    table_name: table.table_name, column_name: name, column_type: String(col.type || ''),
    category: personal ? best.category : (best ? 'possible_' + best.category : 'none'),
    sensitivity: personal ? best.sensitivity : 'none',
    confidence: best ? best.confidence : 0,
    source: best ? best.source : 'none',
    evidence: best ? best.evidence : 'no pattern matched the name or the sampled values',
    sample_shape: samples.slice(0, 3).map(mask).join(' | '),
    rows_sampled: rows.length,
    personal
  } });
}
if (!cols.length) out.push({ json: { table_name: table.table_name, column_name: '(no columns)', column_type: '', category: 'none', sensitivity: 'none', confidence: 0, source: 'none', evidence: 'table has no columns', sample_shape: '', rows_sampled: rows.length, personal: false } });
return out;

// After the loop: build one compact description per table for the judge. Column names and masked shapes only.
const raw = $input.all().map(i => i.json).filter(r => r && r.table_name);
// The loop hands the same column back once per sampled row, so collapse to one entry per
// table+column before anything is counted, prompted or stored. Counting the duplicates is how a
// run reports 4,170 columns across 39 tables, repeats one finding fifteen times, and builds a
// judge prompt so large the model refuses it.
const seenCol = new Set();
const items = [];
for (const r of raw) {
  const key = r.table_name + '::' + r.column_name;
  if (seenCol.has(key)) continue;
  seenCol.add(key);
  items.push(r);
}
const tables = {};
for (const r of items) { (tables[r.table_name] = tables[r.table_name] || []).push(r); }
// The judge may only ADD a column, so show it only the columns the rules left unmarked, and cap the
// list. Measured on a real instance: sending all 278 columns of 39 tables produced a prompt the model
// answered with malformed JSON, and before the de-duplication fix it refused the request outright.
// Raise these two numbers if your model copes; a larger prompt buys nothing once it stops answering.
const JUDGE_MAX_TABLES = 12;
const JUDGE_MAX_COLUMNS_PER_TABLE = 8;
const candidates = Object.entries(tables)
  .map(function (e) { return [e[0], e[1].filter(function (c) { return !c.personal; }).slice(0, JUDGE_MAX_COLUMNS_PER_TABLE)]; })
  .filter(function (e) { return e[1].length; })
  .slice(0, JUDGE_MAX_TABLES);
const lines = candidates.map(function (e) {
  return e[0] + ': ' + e[1].map(function (c) { return c.column_name + ' [shape ' + (c.sample_shape || 'empty') + ']'; }).join(', ');
});
const judgePrompt = 'UNCLASSIFIED COLUMNS (table: column [masked sample shape], ...):\n' + lines.join('\n') +
  '\n\nFor each table listed, guess in a few words what it is for. Then list any column above that clearly holds personal data by its name or shape, with a category from: contact, identity, financial, online, health, biometric, belief, criminal. Only columns shown above. If a table has none, give it with an empty list. Reply with JSON matching the schema and nothing else.';
return [{ json: { run_id: $execution.id, scanned_at: new Date().toISOString(), tables_scanned: Object.keys(tables).length, columns_scanned: items.length, personal_columns: items.filter(r => r.personal).length, special_category_columns: items.filter(r => r.personal && r.sensitivity === 'special').length, items, judge_tables_shown: candidates.length, judge_prompt: judgePrompt } }];

const p = $('Prepare The Judge Input').first().json;
const judgeItem = $input.first().json || {};
const out = judgeItem.output && typeof judgeItem.output === 'object' ? judgeItem.output : null;
const allowed = ['contact', 'identity', 'financial', 'online', 'health', 'biometric', 'belief', 'criminal'];
const special = ['health', 'biometric', 'belief', 'criminal'];
const items = p.items.map(r => Object.assign({}, r));
const byKey = {}; for (const r of items) byKey[r.table_name + '|' + r.column_name] = r;
const purposes = {};
let judgeStatus, added = 0, rejected = [];
if (out && Array.isArray(out.tables)) {
  judgeStatus = 'answered';
  for (const t of out.tables) {
    const tn = String((t && t.table_name) || '');
    if (t && t.purpose) purposes[tn] = String(t.purpose).slice(0, 120);
    for (const a of (Array.isArray(t && t.extra_personal_columns) ? t.extra_personal_columns : [])) {
      const key = tn + '|' + String((a && a.column_name) || '');
      const cat = String((a && a.category) || '').toLowerCase();
      const row = byKey[key];
      if (!row) { rejected.push(key + ': no such column'); continue; }
      if (row.personal) { rejected.push(key + ': already marked'); continue; }
      if (!allowed.includes(cat)) { rejected.push(key + ': unknown category ' + cat); continue; }
      row.personal = true; row.category = cat; row.sensitivity = special.includes(cat) ? 'special' : 'personal'; row.confidence = 60; row.source = 'judge';
      row.evidence = 'the model marked it from the column name and masked shape' + (a.reason ? ': ' + String(a.reason).slice(0, 120) : '');
      added += 1;
    }
  }
} else {
  judgeStatus = 'did not answer' + (judgeItem.error ? ': ' + String(judgeItem.error.message || judgeItem.error).slice(0, 120) : '');
}
for (const r of items) { r.run_id = p.run_id; r.scanned_at = p.scanned_at; r.table_purpose = purposes[r.table_name] || ''; }
const personal = items.filter(r => r.personal);
const specials = personal.filter(r => r.sensitivity === 'special');
const perTable = {}; for (const r of personal) { (perTable[r.table_name] = perTable[r.table_name] || []).push(r.column_name); }
const summary = p.tables_scanned + ' tables, ' + p.columns_scanned + ' columns scanned; ' + personal.length + ' personal data columns in ' + Object.keys(perTable).length + ' tables, ' + specials.length + ' special-category columns' + (specials.length ? ' (' + specials.map(r => r.table_name + '.' + r.column_name).join(', ') + ')' : '') + '. Judge ' + judgeStatus + ', added ' + added + (rejected.length ? ', rejected ' + rejected.length : '') + '.';
return [{ json: { run: { run_id: p.run_id, scanned_at: p.scanned_at, tables_scanned: p.tables_scanned, columns_scanned: p.columns_scanned, personal_columns: personal.length, special_category_columns: specials.length, judge_status: judgeStatus, judge_added: added, summary }, items, rejected, per_table: perTable } }];
